#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;

#[test]
fn normalizes_a_relative_path() {
    let file = SiteFile::new("./app/page.tsx", b"x".to_vec()).unwrap();

    assert_eq!(file.path, "app/page.tsx");
    assert_eq!(file.len(), 1);
