}

//! Tests for the `TinyBus` module adapter and its declared surface.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use serde_json::json;
use tinybus::broker::Broker;
use tinybus::transport::memory::MemoryBus;
use tinybus::{Connection, Interface};
use wiremock::matchers::{method, path};
use wiremock::{Mock, MockServer, ResponseTemplate};

use super::{HostingService, INTERFACE, OBJECT_PATH, setup};

/// A client connected to a bus with the module already serving on it.
///
/// The service connection is returned alongside the client: dropping it drops
/// the name it claimed, and every call would then fail with `NameHasNoOwner`.
async fn connect() -> tinybus::Result<(Connection, Connection)> {
    let bus = MemoryBus::new();
    Broker::new().spawn(bus.clone());

    let service = Connection::connect(bus.connect().await?).await?;
    setup(service.clone()).await?;

    let client = Connection::connect(bus.connect().await?).await?;
    Ok((service, client))
}

#[test]
fn declared_methods_match_the_dispatch_table() {
    let methods = HostingService
        .members()
        .into_iter()
        .map(|member| member.to_string())
        .collect::<Vec<_>>();

    assert_eq!(methods, ["Execute", "Providers"]);
}

#[tokio::test]
async fn the_module_reports_the_providers_this_build_has() -> tinybus::Result<()> {
    let (_service, client) = connect().await?;
    let proxy = client.proxy(INTERFACE, OBJECT_PATH, INTERFACE)?;

    let providers: String = proxy.call("Providers", ()).await?;

    assert_eq!(providers, r#"["vercel"]"#);
    Ok(())
}

#[tokio::test]
async fn the_module_runs_a_hosting_request() -> tinybus::Result<()> {
    let server = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/v10/projects"))
        .respond_with(
            ResponseTemplate::new(200)
                .set_body_json(json!({"projects": [{"id": "prj_1", "name": "shop"}]})),
        )
        .mount(&server)
        .await;

    let (_service, client) = connect().await?;
    let proxy = client.proxy(INTERFACE, OBJECT_PATH, INTERFACE)?;

    let request = json!({
        "operation": "list_sites",
        "credentials": {"api_key": "token"},
        "base_url": server.uri(),
    })
    .to_string();
    let response: String = proxy.call("Execute", (request,)).await?;

    assert!(response.contains(r#""result":"sites""#), "{response}");
    assert!(response.contains("prj_1"), "{response}");
    Ok(())
}

#[tokio::test]
async fn a_failed_request_becomes_a_bus_error_carrying_the_reason() -> tinybus::Result<()> {
    let (_service, client) = connect().await?;
    let proxy = client.proxy(INTERFACE, OBJECT_PATH, INTERFACE)?;

    let result = proxy
        .call::<String>("Execute", ("{ not an envelope }".to_owned(),))
        .await;

    let Err(error) = result else {
        return Err(tinybus::Error::failed(
            "a malformed envelope unexpectedly succeeded",
        ));
    };
    assert!(
        error
            .to_string()
            .contains("cannot decode the request envelope"),
        "{error}"
    );
    Ok(())
}

//! Unit tests for provider naming, credential lookup, and connection.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::collections::HashMap;

// `FromStr` is NOT imported here: `use super::*` already brings the parent
// module's own `use std::str::FromStr` into scope, so a second import is
// redundant. Rust 1.98 started reporting it, and `-D warnings` turned that
// report into a build failure — see the commit message.
use super::*;

fn lookup(pairs: &[(&str, &str)]) -> impl Fn(&str) -> Option<String> + use<> {
    let map: HashMap<String, String> = pairs
        .iter()
        .map(|(key, value)| ((*key).to_owned(), (*value).to_owned()))
        .collect();

    move |name: &str| map.get(name).cloned()
}

#[test]
fn a_provider_names_itself() {
    assert_eq!(ProviderKind::Vercel.as_str(), "vercel");
    assert_eq!(ProviderKind::Vercel.to_string(), "vercel");
    assert_eq!(ProviderKind::default(), ProviderKind::Vercel);
}

#[test]
fn a_provider_parses_case_insensitively() {
    assert_eq!(
        ProviderKind::from_str("vercel").unwrap(),
        ProviderKind::Vercel
    );
    assert_eq!(
        ProviderKind::from_str("  VERCEL ").unwrap(),
        ProviderKind::Vercel
    );
}

#[test]
fn an_unknown_provider_is_rejected_by_name() {
    let error = ProviderKind::from_str("heroku").unwrap_err();

    assert_eq!(
        error,
        Error::UnknownProvider {
            name: "heroku".to_owned()
        }
    );
}

#[test]
fn the_prefixed_variable_wins() {
    let credentials = ProviderKind::Vercel
        .credentials_from(&lookup(&[
            ("TINYHOSTS_VERCEL_TOKEN", "ours"),
            ("VERCEL_TOKEN", "the-cli-token"),
        ]))
        .unwrap();

    assert_eq!(credentials.api_key(), "ours");
}

#[test]
fn the_providers_own_variable_is_a_fallback() {
    let credentials = ProviderKind::Vercel
        .credentials_from(&lookup(&[
            ("TINYHOSTS_VERCEL_TOKEN", "   "),
            ("VERCEL_TOKEN", "the-cli-token"),
            ("VERCEL_TEAM_ID", "team_abc"),
        ]))
        .unwrap();

    assert_eq!(credentials.api_key(), "the-cli-token");
    assert_eq!(credentials.team(), Some("team_abc"));
}

#[test]
fn a_missing_key_names_every_variable_it_searched() {
    let error = ProviderKind::Vercel
        .credentials_from(&lookup(&[]))
        .unwrap_err();

    assert_eq!(
        error,
        Error::MissingApiKey {
            provider: "vercel".to_owned(),
            variables: "TINYHOSTS_VERCEL_TOKEN, VERCEL_TOKEN".to_owned(),
        }
    );
}

#[test]
fn reading_the_process_environment_either_finds_a_key_or_says_so() {
    // The test suite must not depend on the machine it runs on: either outcome
    // is correct here, and running the call is what exercises the lookup.
    match ProviderKind::Vercel.credentials_from_env() {
        Ok(credentials) => assert!(!credentials.api_key().is_empty()),
        Err(error) => assert!(matches!(error, Error::MissingApiKey { .. })),
    }
}

#[test]
fn variable_lists_are_stable() {
    assert_eq!(
        ProviderKind::Vercel.api_key_variables(),
        &["TINYHOSTS_VERCEL_TOKEN", "VERCEL_TOKEN"]
    );
    assert_eq!(
        ProviderKind::Vercel.team_variables(),
        &["TINYHOSTS_VERCEL_TEAM_ID", "VERCEL_TEAM_ID"]
    );
}

#[test]
fn connecting_yields_a_host_for_the_named_provider() {
    let host = connect(ProviderKind::Vercel, Credentials::new("token").unwrap()).unwrap();

    assert_eq!(host.kind(), ProviderKind::Vercel);
}

#[test]
fn connecting_can_target_another_api_root() {
    let host = connect_to(
        ProviderKind::Vercel,
        Credentials::new("token").unwrap(),
        Some("http://127.0.0.1:1"),
    )
    .unwrap();

    assert_eq!(host.kind(), ProviderKind::Vercel);
}

#[test]
fn connecting_over_plain_http_to_a_non_loopback_host_is_rejected() {
    let error = connect_to(
        ProviderKind::Vercel,
        Credentials::new("token").unwrap(),
        Some("http://api.example.com"),
    )
    .unwrap_err();

    assert_eq!(
        error,
        Error::InsecureBaseUrl {
            base_url: "http://api.example.com".to_owned()
        }
    );
}

#[test]
fn connecting_over_https_to_any_host_is_allowed() {
    let host = connect_to(
        ProviderKind::Vercel,
        Credentials::new("token").unwrap(),
        Some("https://api.example.com"),
    )
    .unwrap();

    assert_eq!(host.kind(), ProviderKind::Vercel);
}

#[test]
fn connecting_over_plain_http_to_localhost_is_allowed() {
    let host = connect_to(
        ProviderKind::Vercel,
        Credentials::new("token").unwrap(),
        Some("http://localhost:1"),
    )
    .unwrap();

    assert_eq!(host.kind(), ProviderKind::Vercel);
}

#[test]
fn connecting_from_the_environment_either_works_or_reports_the_missing_key() {
    match connect_from_env(ProviderKind::Vercel) {
        Ok(host) => assert_eq!(host.kind(), ProviderKind::Vercel),
        Err(error) => assert!(matches!(error, Error::MissingApiKey { .. })),
    }
}
